// This sketch paints a sunset over green hills.
// The brush is used to draw a sky, green hills, and a red sun.

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4"); // Sky color

  // Draw the green hills
  brush.fill("#e08a72", 0.3); // Green hills
  brush.fillBleed(0.8); // Spread the green hills
  brush.circle(200, 100, 200); // Draw a hill

  // Draw the sun
  brush.fill("#e08a72", 1); // Red sun
  brush.fillBleed(0.8); // Spread the sun
  brush.beginShape();
  brush.vertex(100, 150); // Top of the sun
  brush.vertex(100, 250); // Right of the sun
  brush.vertex(200, 250); // Bottom of the sun
  brush.endShape(true); // Draw the sun
}
```

