// This code draws a sunset over green hills using the p5.brush library.
// The sun is a filled shape, and the hills are a series of filled shapes.

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Draw the sun
  brush.fill("#f26022", 100); // Fill the sun with a red color
  brush.fillBleed(0.8); // Make the sun slightly transparent
  brush.beginShape();
  brush.vertex(0, 0); // Top of the sun
  brush.vertex(400, 0); // Bottom of the sun
  brush.vertex(0, 400); // Right side of the sun
  brush.vertex(400, 400); // Left side of the sun
  brush.endShape(true);

  // Draw the hills
  brush.fill("#5f9c5f", 100); // Fill the hills with a green color
  brush.fillBleed(0.3); // Make the hills slightly transparent
  brush.beginShape();
  brush.vertex(0, 0); // Top of the hill
  brush.vertex(200, 0); // Bottom of the hill
  brush.vertex(0, 200); // Right side of the hill
  brush.vertex(200, 200); // Left side of the hill
  brush.endShape(true); // Close the hill shape
}
```

